 game('lights','Lights Out','Puzzle','☷','green',createLights,{description:'Flip a switch. Think a step ahead.',eyebrow:'FIVE CIRCUITS. ONE BRIGHT IDEA.',intro:'Find the beauty in a blackout.',hint:'Tap flips a light and its + neighbors. Turn all off.',instructions:'Tap a tile to flip it and its up, down, left and right neighbors. Turn every light off to clear a circuit. Solve five increasingly tangled circuits. Every circuit has a solution. Fewer moves earn more points. Arrow keys select; Space flips.',chips:['Tap a light','Five circuits','Arrows + Space']}),
 game('echo','Echo','Memory','◴','violet',createEcho,{scoreLabel:'ROUNDS',description:'Four notes. A pattern worth remembering.',eyebrow:'WATCH. LISTEN. PLAY IT BACK.',intro:'A little melody in your memory.',hint:'Watch the pads, then repeat their sequence.',instructions:'Watch and listen as the four pads light up. When YOUR TURN appears, tap them in the same order. Each completed pattern adds one note. One wrong note ends the round. Arrow keys trigger the matching arrow on each pad. Music rests so the four notes stay clear.',chips:['Watch, then repeat','Four musical pads','Arrow keys']}),
 game('four','Four in a Row','Strategy','⠿','gold',createFour,{description:'A friendly duel with a few moves up its sleeve.',eyebrow:'THINK AHEAD. CONNECT FOUR.',intro:'Your move.',hint:'Tap a column. Connect four before the CPU.',instructions:'You play the gold discs. Tap a column to drop one, then the CPU takes its turn. Connect four horizontally, vertically, or diagonally. Watch for threats on both ends of a line. Arrow keys choose a column; Space drops. The CPU plans several moves ahead.',chips:['Tap a column','You vs CPU','Arrows + Space']}),
 game('reversi','Reversi','Strategy','◐','mint',createReversi,{scoreLabel:'DISCS',description:'One move can change the whole board.',eyebrow:'SMALL BOARD. BIG REVERSALS.',intro:'Turn things around.',hint:'Tap a dot. Sandwich their discs to flip them.',instructions:'You are mint on this quick 6×6 board. Put a disc on a marked square to sandwich and flip a line of violet discs. Capture horizontally, vertically or diagonally. Turns pass automatically when no legal move exists. Finish with more discs than the CPU. Arrow keys select; Space places.',chips:['Tap a legal move','Quick 6×6 board','Arrows + Space']}),
 game('bubbles','Bubble Sky','Classic','◌','violet',createBubbles,{description:'Bank a shot. Pop a cluster. Watch it all fall.',eyebrow:'A LITTLE ROOM ABOVE THE CLOUDS.',intro:'Let the good things pop.',hint:'Aim and release. Match 3. Drop hanging clusters.',instructions:'Aim by dragging, then release to shoot. Match three or more numbered bubbles of the same color. Bubbles disconnected from the ceiling fall for double points. Bank shots off the side walls. Five shots without a match bring the ceiling down. Clear every bubble to win. Left/right aim; Space shoots.',chips:['Aim, then release','Match three','Bank off walls']}),
 game('golf','Pocket Golf','Precision','⚑','green',createGolf,{description:'Five little courses. A very satisfying little plunk.',eyebrow:'TAKE THE SCENIC ROUTE.',intro:'Just a gentle nudge.',hint:'Pull back anywhere. Release to putt.',instructions:'Complete five courses in 20 strokes. Pull back anywhere to set direction and power, then release. The dotted line shows your aim. The ball bounces off rails, slows on the green, and drops into the cup at a gentle speed. Left/right aim, up/down set power, and Space putts.',chips:['Pull back to aim','Release to putt','Five holes']}),
 game('hoops','Swish','Sport','◉','gold',createHoops,{description:'Ten shots. A moving hoop. Nothing but net.',eyebrow:'BREATHE. SHOOT. SWISH.',intro:'Find your shooting touch.',hint:'Pull down for power. Angle your pull to aim.',instructions:'Take ten shots. Pull down to set power, angle your pull to aim, then release. The dotted arc previews your launch. Score by dropping the ball through the hoop from above. Consecutive baskets earn bonuses; the hoop moves farther as your score rises. Left/right aim, up/down set power, Space shoots.',chips:['Pull to aim','Release to shoot','Ten shots']}),
 game('sprint','Lane Rush','Racer','⇈','blue',createSprint,{description:'Sixty seconds in the fast lane.',eyebrow:'FIND YOUR OPENING.',intro:'A little room to move.',hint:'Tap a lane or swipe sideways. Dodge and collect.',instructions:'Survive a 60-second highway sprint. Tap one of three lanes, swipe sideways, or use left/right arrows to change lanes. Dodge vehicles and collect gold tokens. You have three lives and brief protection after a collision. Every traffic row leaves a lane open. Speed builds gradually.',chips:['Tap a lane','Swipe or ← →','60 seconds']}),
 game('slice','Prism Slice','Reflex','◇','pink',createSlice,{description:'A sweep of your finger. A shower of color.',eyebrow:'MAKE A CLEAN CUT.',intro:'A little spark at your fingertips.',hint:'Swipe through gems. Avoid the marked × hazards.',instructions:'Swipe through airborne gems to slice them. Catch several in one sweep for up to a five-times combo. Avoid the red × hazards. A dropped gem or sliced hazard costs a life. Survive 45 seconds with three lives. Arrow keys move and cut with the reticle; Space makes a wider slash.',chips:['Swipe to slice','Chain combos','Avoid ×']}),
 game('orbit','Orbit','Timing','◔','violet',createOrbit,{description:'One orbit. One moment. One more perfect tap.',eyebrow:'EVERYTHING COMES AROUND.',intro:'Meet in the right moment.',hint:'Tap when the white dot reaches the lit arc.',instructions:'Tap or press Space when the white dot enters the highlighted arc. Hit its center for double points. Targets get smaller and the orbit speeds up. Every five hits reverses direction. You have three misses and 45 seconds. Wait for your moment; extra taps cost a life.',chips:['One tap','Space','Perfect center bonus']}),
 game('maze','Maze Escape','Explorer','⊞','green',createMaze,{description:'Follow your curiosity. Leave a little trail.',eyebrow:'THERE IS ALWAYS A WAY THROUGH.',intro:'Find your own way.',hint:'Trace the paths. Collect 3 sparks. Find the exit.',instructions:'Collect all three gold sparks and reach the marked exit. Clear three fresh mazes, each with 55 seconds. Drag through neighboring passages, swipe a direction, or tap on the side you want to step toward. Arrow keys also move. Your trail marks visited cells. Every passage is connected.',chips:['Trace or swipe','Collect 3 sparks','Arrow keys']}),
 game('rhythm','Beat Drop','Rhythm','♬','blue',createRhythm,{description:'Four lanes. Sixty-four beats. Your next flow state.',eyebrow:'LET YOUR FINGERS FIND THE BEAT.',intro:'Fall into a rhythm.',hint:'Tap a lane as its tile reaches the white line.',instructions:'Tap a lane as its falling tile reaches the white line. Accurate hits earn PERFECT bonuses and build a combo. Complete the 64-note phrase with five lives. The second half picks up the tempo. Use left, up, down, right for the four lanes, or Space to play the next due tile.',chips:['Tap on the line','64-note phrase','← ↑ ↓ →']})
